entries.commands:
# ⚠ 临时生效：重启网络/机器后失效，持久化见配套条目：《永久配置 IP（ifcfg-* 文件）》
ip addr show
ip addr add {{ip_addr}}/{{prefix_len}} dev {{ifname}}
ip link set {{ifname}} up
ip addr show {{ifname}}
# 验证连通
ping -c 2 {{gateway}}
# 清除该 IP（需要时）：
# ip addr del {{ip_addr}}/{{prefix_len}} dev {{ifname}}

entries.rollback:
# 回退：删除临时添加的 IP（临时生效，重启网络/机器自动消失；手动清除如下）
ip addr del {{ip_addr}}/{{prefix_len}} dev {{ifname}}
# 复核
ip addr show {{ifname}}

entries.commands:
# 持久化配置：/etc/sysconfig/network-scripts/ifcfg-{{ifname}}
# 改之前先备份！
cp /etc/sysconfig/network-scripts/ifcfg-{{ifname}} /etc/sysconfig/network-scripts/ifcfg-{{ifname}}.bak
vi /etc/sysconfig/network-scripts/ifcfg-{{ifname}}
# ---- 文件内容（按现场实际填写）----
# DEVICE={{ifname}}
# BOOTPROTO=static
# ONBOOT=yes
# IPADDR={{ip_addr}}
# PREFIX={{prefix_len}}
# GATEWAY={{gateway}}
# DNS1={{dns_ip}}
# ------------------------------------
systemctl restart network
ip addr show {{ifname}}
ip route show

nmcli con show
nmcli con mod "{{con_name}}" ipv4.method manual ipv4.addresses {{ip_addr}}/{{prefix_len}}
nmcli con mod "{{con_name}}" ipv4.gateway {{gateway}}
nmcli con mod "{{con_name}}" ipv4.dns {{dns_ip}}
nmcli con up "{{con_name}}"
nmcli con show "{{con_name}}"
ip addr show {{ifname}}

# ⚠ 临时生效：持久化见配套条目：《静态路由持久化（route-* 文件）》
ip route show
ip route add {{dest_net}}/{{prefix_len}} via {{gateway}} dev {{ifname}}
ip route show
# 删除该路由（需要时）：
# ip route del {{dest_net}}/{{prefix_len}} via {{gateway}}

# 持久化：/etc/sysconfig/network-scripts/route-{{ifname}}
vi /etc/sysconfig/network-scripts/route-{{ifname}}
# ---- 文件内容（每行一条路由）----
# {{dest_net}}/{{prefix_len}} via {{gateway}} dev {{ifname}}
systemctl restart network
ip route show

# ⚠ 临时生效：持久化见配套条目：《VLAN 子接口持久化（ifcfg 文件）》
# 前提：交换机侧该口已配 trunk 并放通该 VLAN
modprobe 8021q
ip link add link {{ifname}} name {{ifname}}.{{vlan_id}} type vlan id {{vlan_id}}
ip addr add {{ip_addr}}/{{prefix_len}} dev {{ifname}}.{{vlan_id}}
ip link set {{ifname}}.{{vlan_id}} up
ip -d link show {{ifname}}.{{vlan_id}}

entries.rollback:
# 回退：删除临时 VLAN 子接口（临时生效；8021q 模块保留无害不必卸载）
ip link del {{ifname}}.{{vlan_id}}
# 复核（期望报不存在）
ip -d link show {{ifname}}.{{vlan_id}}

entries.commands:
# 持久化：/etc/sysconfig/network-scripts/ifcfg-{{ifname}}.{{vlan_id}}
cat > /etc/sysconfig/network-scripts/ifcfg-{{ifname}}.{{vlan_id}} << 'EOF'
DEVICE={{ifname}}.{{vlan_id}}
BOOTPROTO=static
ONBOOT=yes
VLAN=yes
PHYSDEV={{ifname}}
IPADDR={{ip_addr}}
PREFIX={{prefix_len}}
EOF
systemctl restart network
ip -d link show {{ifname}}.{{vlan_id}}

entries.rollback:
# 回退：变更时未备份 ifcfg 文件——本次新建则直接删除后重启网络
#（若该文件此前已存在，按变更记录恢复原内容）
rm -f /etc/sysconfig/network-scripts/ifcfg-{{ifname}}.{{vlan_id}}
systemctl restart network
# 复核（期望报不存在）
ip -d link show {{ifname}}.{{vlan_id}}

entries.commands:
systemctl start {{service_name}}
systemctl stop {{service_name}}
systemctl restart {{service_name}}
systemctl status {{service_name}} --no-pager
systemctl is-enabled {{service_name}}
# 开机自启 / 取消自启
systemctl enable {{service_name}}
systemctl disable {{service_name}}
# 起不来时看细节
systemctl status {{service_name}} -l --no-pager
journalctl -u {{service_name}} -n 50 --no-pager

systemctl is-enabled {{service_name}}
systemctl list-unit-files --type=service --state=enabled --no-pager
systemctl list-unit-files --type=service --state=disabled --no-pager | head -20
# 某服务开机自启被谁依赖/依赖谁
systemctl list-dependencies {{service_name}}

ss -tlnp | grep :{{port}}
ss -tlnp
ss -s
# netstat 用法相同（需 yum install net-tools）
netstat -tlnp | grep :{{port}}
# 查某进程占了哪些端口
ss -tlnp | grep {{pid}}

ethtool {{ifname}}
ethtool -i {{ifname}}
ethtool -S {{ifname}} | grep -iE "error|drop|crc" | head
ip -s link show {{ifname}}

ping -c 4 {{peer_ip}}
traceroute {{peer_ip}}
dig @{{dns_ip}} {{domain}} +short
# 指定出口网卡 ping（多网卡/策略路由场景）
ping -I {{ifname}} -c 4 {{peer_ip}}
# 端口级连通（比 telnet 直观）
curl -v telnet://{{peer_ip}}:{{port}} --connect-timeout 3
